-- Reference migration for the paused jobs of the relational job queue
-- (`TomSqlJobStore.pauseJob`).
--
-- Creates the `tom_job_pause` table: one row per paused job, deleted when the
-- job is resumed. This file is the canonical DDL and is kept in sync with
-- `jobPauseTableDdl()` in `lib/src/tomserver/scheduling/sql_scheduling_sql.dart`;
-- `test/scheduling_schema_test.dart` fails if the two drift apart.
--
-- A pause belongs to the job, not to its runs, so it is a table of its own
-- rather than a flag on `tom_job_run`: runs enqueued while the job is paused
-- wait too, and a job with no runs yet can still be paused. The claim scan
-- leaves out every job named here, on every node sharing the queue.
--
-- `paused_at` is written in UTC by the store.
CREATE TABLE IF NOT EXISTS tom_job_pause (
  job_name VARCHAR(150) NOT NULL,
  paused_at TIMESTAMP(6) NOT NULL,
  PRIMARY KEY (job_name)
);
